window.COURSE_DATA={"version":1,"title":"LifeScience 11","topics":["Levels of Organization","Cell Structure and Function","Cell Cycle: Mitosis and Meiosis","Photosynthesis and Cellular Respiration","Viruses","Evolution","Genetic Engineering","Asexual and Sexual Reproduction","Immunization and Vaccination"],"units":[{"id":"levels","title":"Levels of Organization Notes","topic":0,"description":"Explore eight levels of life, from cells to ecosystems, with the original picture exercises.","href":"units/levels/index.html","image":"units/levels/images/page-12.jpg","pages":52,"verified":true,"pointCount":10,"questionCount":59},{"id":"cells","title":"Concept 1 · Cell Theory and Organelles","topic":1,"description":"Explore animal and plant cells, connect structures with functions, and practise each learning objective.","href":"units/cells/index.html","image":"units/cells/assets/animal.png","pages":31,"verified":false,"pointCount":27,"questionCount":37}],"points":[{"id":"levels-cell","key":"cell","unit":"levels","title":"Cell","pages":"2","href":"units/levels/index.html#level-cell","verified":true},{"id":"levels-tissue","key":"tissue","unit":"levels","title":"Tissue","pages":"3","href":"units/levels/index.html#level-tissue","verified":true},{"id":"levels-organ","key":"organ","unit":"levels","title":"Organ","pages":"4","href":"units/levels/index.html#level-organ","verified":true},{"id":"levels-system","key":"system","unit":"levels","title":"Organ system","pages":"5","href":"units/levels/index.html#level-system","verified":true},{"id":"levels-organism","key":"organism","unit":"levels","title":"Organism","pages":"6","href":"units/levels/index.html#level-organism","verified":true},{"id":"levels-population","key":"population","unit":"levels","title":"Population","pages":"7","href":"units/levels/index.html#level-population","verified":true},{"id":"levels-community","key":"community","unit":"levels","title":"Community","pages":"8","href":"units/levels/index.html#level-community","verified":true},{"id":"levels-ecosystem","key":"ecosystem","unit":"levels","title":"Ecosystem","pages":"9","href":"units/levels/index.html#level-ecosystem","verified":true},{"id":"levels-hierarchy","key":"hierarchy","unit":"levels","title":"Structural hierarchy and relationships","pages":"1–9","href":"units/levels/index.html#hierarchy","verified":true},{"id":"levels-life-processes","key":"life-processes","unit":"levels","title":"Life processes","pages":"6","href":"units/levels/index.html#life-processes","verified":true},{"id":"cells-theory","key":"theory","unit":"cells","title":"Cell theory","pages":"2–3","href":"units/cells/index.html#fact-theory","verified":false,"topic":1},{"id":"cells-organization","key":"organization","unit":"cells","title":"Unicellular & multicellular","pages":"2–3","href":"units/cells/index.html#fact-organization","verified":false,"topic":1},{"id":"cells-prokaryote","key":"prokaryote","unit":"cells","title":"Prokaryotic cell","pages":"4–7","href":"units/cells/index.html#fact-prokaryote","verified":false,"topic":2},{"id":"cells-eukaryote","key":"eukaryote","unit":"cells","title":"Eukaryotic cell","pages":"4–7","href":"units/cells/index.html#fact-eukaryote","verified":false,"topic":2},{"id":"cells-shared","key":"shared","unit":"cells","title":"Four shared components","pages":"4–7","href":"units/cells/index.html#fact-shared","verified":false,"topic":2},{"id":"cells-organelles","key":"organelles","unit":"cells","title":"Organelles","pages":"4–7","href":"units/cells/index.html#fact-organelles","verified":false,"topic":2},{"id":"cells-membrane","key":"membrane","unit":"cells","title":"Cell / plasma membrane","pages":"10–13","href":"units/cells/index.html#fact-membrane","verified":false,"topic":3},{"id":"cells-bilayer","key":"bilayer","unit":"cells","title":"Fluid-mosaic model","pages":"10–13","href":"units/cells/index.html#fact-bilayer","verified":false,"topic":3},{"id":"cells-cytoplasm","key":"cytoplasm","unit":"cells","title":"Cytoplasm","pages":"10–13","href":"units/cells/index.html#fact-cytoplasm","verified":false,"topic":3},{"id":"cells-cytoskeleton","key":"cytoskeleton","unit":"cells","title":"Cytoskeleton","pages":"10–13","href":"units/cells/index.html#fact-cytoskeleton","verified":false,"topic":3},{"id":"cells-nucleus","key":"nucleus","unit":"cells","title":"Nucleus","pages":"14–15","href":"units/cells/index.html#fact-nucleus","verified":false,"topic":4},{"id":"cells-nucleolus","key":"nucleolus","unit":"cells","title":"Nucleolus","pages":"14–15","href":"units/cells/index.html#fact-nucleolus","verified":false,"topic":4},{"id":"cells-ribosome","key":"ribosome","unit":"cells","title":"Ribosome","pages":"16–17","href":"units/cells/index.html#fact-ribosome","verified":false,"topic":5},{"id":"cells-rough-er","key":"rough-er","unit":"cells","title":"Rough endoplasmic reticulum · RER","pages":"16–17","href":"units/cells/index.html#fact-rough-er","verified":false,"topic":5},{"id":"cells-smooth-er","key":"smooth-er","unit":"cells","title":"Smooth endoplasmic reticulum · SER","pages":"18–19","href":"units/cells/index.html#fact-smooth-er","verified":false,"topic":6},{"id":"cells-golgi","key":"golgi","unit":"cells","title":"Golgi apparatus","pages":"18–19","href":"units/cells/index.html#fact-golgi","verified":false,"topic":6},{"id":"cells-vesicle","key":"vesicle","unit":"cells","title":"Vesicle","pages":"18–19","href":"units/cells/index.html#fact-vesicle","verified":false,"topic":6},{"id":"cells-lysosome","key":"lysosome","unit":"cells","title":"Lysosome","pages":"20–21, 27","href":"units/cells/index.html#fact-lysosome","verified":false,"topic":7},{"id":"cells-vacuole","key":"vacuole","unit":"cells","title":"Vacuole","pages":"20–21, 27","href":"units/cells/index.html#fact-vacuole","verified":false,"topic":7},{"id":"cells-central-vacuole","key":"central-vacuole","unit":"cells","title":"Central vacuole","pages":"20–21, 27","href":"units/cells/index.html#fact-central-vacuole","verified":false,"topic":7},{"id":"cells-centrosome","key":"centrosome","unit":"cells","title":"Centrosome & centrioles","pages":"22–23","href":"units/cells/index.html#fact-centrosome","verified":false,"topic":8},{"id":"cells-cilia","key":"cilia","unit":"cells","title":"Cilia","pages":"22–23","href":"units/cells/index.html#fact-cilia","verified":false,"topic":8},{"id":"cells-flagella","key":"flagella","unit":"cells","title":"Flagella","pages":"22–23","href":"units/cells/index.html#fact-flagella","verified":false,"topic":8},{"id":"cells-mitochondria","key":"mitochondria","unit":"cells","title":"Mitochondrion · plural: mitochondria","pages":"24–25","href":"units/cells/index.html#fact-mitochondria","verified":false,"topic":9},{"id":"cells-chloroplast","key":"chloroplast","unit":"cells","title":"Chloroplast","pages":"24–25","href":"units/cells/index.html#fact-chloroplast","verified":false,"topic":9},{"id":"cells-wall","key":"wall","unit":"cells","title":"Cell wall","pages":"8–9, 26, 28–31","href":"units/cells/index.html#fact-wall","verified":false,"topic":10},{"id":"cells-comparison","key":"comparison","unit":"cells","title":"Animal & plant cells","pages":"8–9, 26, 28–31","href":"units/cells/index.html#fact-comparison","verified":false,"topic":10}],"questions":[{"id":"levels-cell","pointKey":"cell","stem":"Which statement correctly identifies a cell?","options":["The basic unit of structure and function in living organisms","A group of different organs working together","All living and nonliving things in an area","Several populations living in the same area"],"answer":0,"explanation":"Page 2 defines a cell as the basic unit of structure and function in all living organisms. Muscle cells and epidermal cells are examples; tissues and organs are higher structural levels.","pages":[2],"unit":"levels","points":["levels-cell"]},{"id":"levels-tissue","pointKey":"tissue","stem":"A group of muscle cells works together to perform a specific function. Which level does this group represent?","options":["Organism","Organ system","Tissue","Ecosystem"],"answer":2,"explanation":"Page 3 describes tissue as similar cells working together for a specific function and lists muscle tissue as an animal example. An organ combines different tissues.","pages":[3],"unit":"levels","points":["levels-tissue"]},{"id":"levels-organ","pointKey":"organ","stem":"A leaf contains different tissues that work together. Which level of organization is the leaf?","options":["Cell","Organ","Population","Organ system"],"answer":1,"explanation":"An organ is made of different tissues working together for a specific function. Page 4 lists leaves among plant organs, alongside roots, stems, flowers, fruits, buds, tubers, and rhizomes.","pages":[4],"unit":"levels","points":["levels-organ"]},{"id":"levels-system","pointKey":"system","stem":"The stomach, intestines, and other digestive organs work together to carry out digestion. What does this coordinated group form?","options":["A tissue","A single cell","A population","An organ system"],"answer":3,"explanation":"Page 5 defines an organ system as different organs working together to perform a particular set of functions. Digestion is performed by a digestive system; the component stomach is an organ.","pages":[5],"unit":"levels","points":["levels-system"]},{"id":"levels-organism","pointKey":"organism","stem":"Which example represents one complete organism rather than only part of an organism?","options":["A complete plant with its roots and shoots","One leaf on the plant","The entire root system of the plant","A group of cells in a plant tissue"],"answer":0,"explanation":"An organism is an individual living thing made of cells. A complete plant is an organism; a leaf is an organ, a root system is an organ system, and a tissue contains cooperating cells.","pages":[6,26,44],"unit":"levels","points":["levels-organism"]},{"id":"levels-population","pointKey":"population","stem":"Which group meets BOTH requirements for a population in the source notes?","options":["All organisms of different species in a park","All frogs of one species living in one pond","All frogs and fish living in one pond","One frog together with the pond water and rocks"],"answer":1,"explanation":"A population consists of organisms of the same species living in the same area. Different species form multiple populations, and nonliving factors are not members of a population.","pages":[7],"unit":"levels","points":["levels-population"]},{"id":"levels-community","pointKey":"community","stem":"The plant, animal, fungal, and microbial populations living in one park together form which level?","options":["One organism","One population","A community","One tissue"],"answer":2,"explanation":"Page 8 defines a community as groups of different populations living in a given area. These living populations include different species, so they are not one population.","pages":[8],"unit":"levels","points":["levels-community"]},{"id":"levels-ecosystem","pointKey":"ecosystem","stem":"A study includes a park's trees and animals as well as its rocks, water, and soil. Which level includes everything being studied?","options":["A cell","A population","A community only","An ecosystem"],"answer":3,"explanation":"Page 9 includes both living and nonliving things in an ecosystem. A community includes the living populations, while the ecosystem also includes the nonliving surroundings.","pages":[9],"unit":"levels","points":["levels-ecosystem"]},{"id":"levels-hierarchy","pointKey":"hierarchy","stem":"Which sequence orders all eight levels from smaller organizational scope to larger scope?","options":["Cell → tissue → organ → organ system → organism → population → community → ecosystem","Cell → organ → tissue → organ system → organism → population → ecosystem → community","Tissue → cell → organ → organism → organ system → community → population → ecosystem","Cell → tissue → organ → organ system → population → organism → ecosystem → community"],"answer":0,"explanation":"The source progresses from cells to tissues, organs, organ systems, and organisms, followed by populations, communities, and ecosystems. The first five levels describe structures in organisms that have these levels; this is an organization sequence, not a growth timeline.","pages":[1,2,3,4,5,6,7,8,9],"unit":"levels","points":["levels-hierarchy"]},{"id":"levels-life-processes","pointKey":"life-processes","stem":"Which list matches ALL six life processes named on source page 6, in addition to being made of cells?","options":["Movement, photosynthesis, flowering, sleep, hearing, and flight","Energy use, waste excretion, growth, response, reproduction, and use of gases","Energy use, photosynthesis, growth, flowering, reproduction, and use of oxygen only","Waste excretion, flight, speech, sleep, response, and use of gases"],"answer":1,"explanation":"The source lists needs energy, excretes wastes, grows, responds, reproduces, and uses gases. These summarize typical life processes; an individual that cannot reproduce is still alive, and uses gases does not mean every organism requires oxygen.","pages":[6],"unit":"levels","points":["levels-life-processes"]},{"id":"cells-theory","pointKey":"theory","stem":"A student sees one cell divide into two cells. Which statement of cell theory does this observation support?","options":["All organisms must contain many cells.","New cells arise from pre-existing cells.","Organs are the basic units of life.","New cells appear spontaneously from nonliving material."],"answer":1,"explanation":"The two new cells come from an existing cell by division. Cell theory also states that living things consist of cells and that cells are the basic units of life.","pages":"2–3","sourceStatus":"inherited-unverified","unit":"cells","points":["cells-theory"]},{"id":"cells-organization","pointKey":"organization","stem":"An organism carries out all of its life processes within a single cell. How should it be described?","options":["Multicellular, because it carries out many processes.","An organ system, because its parts work together.","Unicellular, because the organism consists of one cell.","A tissue, because the cell has different structures."],"answer":2,"explanation":"Unicellular describes an organism made of one cell. Multicellular organisms consist of many cells; those cells may be organized into tissues, organs, and organ systems.","pages":"2–3","sourceStatus":"inherited-unverified","unit":"cells","points":["cells-organization"]},{"id":"cells-prokaryote","pointKey":"prokaryote","stem":"A bacterial cell has DNA, ribosomes, and a cell membrane, but no membrane-bound nucleus. Which description fits it?","options":["Prokaryotic, because its DNA is not enclosed in a nucleus.","Eukaryotic, because all cells with DNA have a nucleus.","A plant cell, because it contains ribosomes.","Nonliving, because a nucleus is required in every cell."],"answer":0,"explanation":"Prokaryotic cells lack a membrane-bound nucleus and membrane-bound organelles. They still have DNA, ribosomes, cytoplasm, and a cell membrane. Bacteria are a classroom example.","pages":"4–7","sourceStatus":"inherited-unverified","unit":"cells","points":["cells-prokaryote"]},{"id":"cells-eukaryote","pointKey":"eukaryote","stem":"A unicellular organism has a membrane-bound nucleus and membrane-bound organelles. Which conclusion follows?","options":["It must be a bacterium.","It cannot be living because it has only one cell.","It is prokaryotic because it is unicellular.","It is eukaryotic; eukaryotes can be unicellular."],"answer":3,"explanation":"A membrane-bound nucleus identifies the cell as eukaryotic. Being unicellular does not make an organism prokaryotic: some eukaryotes are unicellular and others are multicellular.","pages":"4–7","sourceStatus":"inherited-unverified","unit":"cells","points":["cells-eukaryote"]},{"id":"cells-shared","pointKey":"shared","stem":"Which set of components is shared by typical prokaryotic and eukaryotic cells?","options":["Nucleus, chloroplasts, mitochondria, and a cell wall.","Cell membrane, cytoplasm, ribosomes, and DNA.","Cell wall, central vacuole, nucleus, and DNA.","Chloroplasts, ribosomes, centrioles, and a cell wall."],"answer":1,"explanation":"Both cell types have a boundary membrane, cytoplasm, ribosomes for protein synthesis, and DNA as hereditary material. Prokaryotes do not have a membrane-bound nucleus or membrane-bound organelles.","pages":"4–7","sourceStatus":"inherited-unverified","unit":"cells","points":["cells-shared"]},{"id":"cells-organelles","pointKey":"organelles","stem":"Why are cell organelles sometimes compared with a team's specialized workers?","options":["Each organelle performs every job in the cell on its own.","Every organelle has the same structure and function.","Different cell structures perform particular tasks that support the cell together.","Organelles are complete organs made of many tissues."],"answer":2,"explanation":"Organelles are specialized structures within cells. Their tasks include protein production, transport, energy conversion, storage, and breakdown. They are not tissue-based organs.","pages":"4–7","sourceStatus":"inherited-unverified","unit":"cells","points":["cells-organelles"]},{"id":"cells-membrane","pointKey":"membrane","stem":"A cell must admit needed materials while controlling what leaves. Which structure directly forms this selectively permeable boundary?","options":["The plasma membrane.","The nucleolus.","A ribosome.","A centriole."],"answer":0,"explanation":"The plasma membrane surrounds the cell and regulates exchange with its environment. It consists of a phospholipid bilayer with embedded proteins.","pages":"10–13","sourceStatus":"inherited-unverified","unit":"cells","points":["cells-membrane"]},{"id":"cells-bilayer","pointKey":"bilayer","stem":"Which statement best explains the words 'fluid mosaic' in the fluid-mosaic model of the membrane?","options":["The membrane is a solid wall made of a single kind of molecule.","The membrane is a layer of water without lipids or proteins.","Every membrane component is permanently fixed in one position.","Many components can move within a membrane that contains a mixture of components."],"answer":3,"explanation":"'Fluid' refers to the movement of many membrane components. 'Mosaic' refers to its mixture of components, including proteins in a phospholipid bilayer. 'Bilayer' means two layers of phospholipids.","pages":"10–13","sourceStatus":"inherited-unverified","unit":"cells","points":["cells-bilayer"]},{"id":"cells-cytoplasm","pointKey":"cytoplasm","stem":"Which description best fits the cytoplasm in the course notes?","options":["A rigid outer layer that replaces the cell membrane.","A mainly water-based internal environment for cell structures and activities.","A compartment that contains only the cell's DNA.","A fiber that pulls chromosomes apart during division."],"answer":1,"explanation":"The notes describe cytoplasm as a jelly-like interior made mainly of water. It provides an environment for cell structures and activities; it does not act as glue that immobilizes everything.","pages":"10–13","sourceStatus":"inherited-unverified","unit":"cells","points":["cells-cytoplasm"]},{"id":"cells-cytoskeleton","pointKey":"cytoskeleton","stem":"A cell loses much of its internal protein-fiber network. Which activities would most directly be affected?","options":["Only storing hereditary information.","Only trapping sunlight in chloroplasts.","Maintaining cell shape and moving organelles within the cell.","Making the cellulose wall of a bacterium."],"answer":2,"explanation":"The cytoskeleton is a network of protein fibers. It supports cell shape and helps position and move components, including organelles, inside the cell.","pages":"10–13","sourceStatus":"inherited-unverified","unit":"cells","points":["cells-cytoskeleton"]},{"id":"cells-nucleus","pointKey":"nucleus","stem":"Which pairing correctly connects a nuclear structure with its role?","options":["Nuclear pores regulate exchange; the nucleus contains and protects DNA.","Nuclear pores make sugars; the nucleus contains the central vacuole.","Nuclear pores digest bacteria; the nucleus synthesizes membrane lipids.","Nuclear pores propel the cell; the nucleus packages proteins for shipping."],"answer":0,"explanation":"The nucleus contains DNA and is surrounded by the nuclear envelope. Pores regulate movement into and out of the nucleus, while DNA carries information involved in directing cell activities.","pages":"14–15","sourceStatus":"inherited-unverified","unit":"cells","points":["cells-nucleus"]},{"id":"cells-nucleolus","pointKey":"nucleolus","stem":"Which activity is associated with the nucleolus inside the nucleus?","options":["Capturing light energy to make sugars.","Sorting proteins received from the endoplasmic reticulum.","Digesting worn-out cell structures.","Producing rRNA and helping assemble ribosomal subunits."],"answer":3,"explanation":"The nucleolus produces ribosomal RNA and helps assemble ribosomal subunits. It is a structure inside the nucleus, not another name for the whole nucleus.","pages":"14–15","sourceStatus":"inherited-unverified","unit":"cells","points":["cells-nucleolus"]},{"id":"cells-ribosome","pointKey":"ribosome","stem":"Which structure directly synthesizes proteins, whether free in the cytoplasm or attached to rough ER?","options":["A lysosome.","A ribosome.","A vacuole.","A chloroplast."],"answer":1,"explanation":"Ribosomes synthesize proteins and consist of proteins and rRNA. They can occur free in the cytoplasm or attached to rough ER. Prokaryotic and eukaryotic cells both have ribosomes.","pages":"16–17","sourceStatus":"inherited-unverified","unit":"cells","points":["cells-ribosome"]},{"id":"cells-rough-er","pointKey":"rough-er","stem":"What gives rough endoplasmic reticulum its 'rough' appearance?","options":["A cellulose wall surrounds it.","Its surface is covered by chloroplasts.","Ribosomes are attached to its surface.","Its membrane is completely rigid."],"answer":2,"explanation":"Ribosomes attached to the ER surface make it appear rough. Those ribosomes synthesize proteins, and rough ER supports processing and transport of the associated proteins.","pages":"16–17","sourceStatus":"inherited-unverified","unit":"cells","points":["cells-rough-er"]},{"id":"cells-smooth-er","pointKey":"smooth-er","stem":"Which ER region lacks attached ribosomes and is associated with lipid synthesis?","options":["Smooth endoplasmic reticulum.","Rough endoplasmic reticulum.","The nuclear pore.","The nucleolus."],"answer":0,"explanation":"Smooth ER has no attached ribosomes and makes lipids, including membrane lipids. Rough ER is distinguished by attached ribosomes involved in protein synthesis.","pages":"18–19","sourceStatus":"inherited-unverified","unit":"cells","points":["cells-smooth-er"]},{"id":"cells-golgi","pointKey":"golgi","stem":"Proteins arrive from the ER and must be processed, sorted, and sent to different destinations. Which organelle performs this sorting role?","options":["The central vacuole.","The nucleolus.","A centriole.","The Golgi apparatus."],"answer":3,"explanation":"The Golgi apparatus consists of stacked membrane sacs. It receives material in ER transport vesicles, processes and sorts it, and sends it to appropriate destinations.","pages":"18–19","sourceStatus":"inherited-unverified","unit":"cells","points":["cells-golgi"]},{"id":"cells-vesicle","pointKey":"vesicle","stem":"What carries material from the ER to the Golgi as a small membrane-bound package?","options":["A ribosome.","A transport vesicle.","A chromosome.","A cilium."],"answer":1,"explanation":"A vesicle is a small membrane-bound sac that transports material between the ER, Golgi, and other destinations. It acts as a carrier rather than as the main protein-synthesis site.","pages":"18–19","sourceStatus":"inherited-unverified","unit":"cells","points":["cells-vesicle"]},{"id":"cells-lysosome","pointKey":"lysosome","stem":"An animal cell needs to digest worn cell components and recover useful materials. Which structure is best suited to this job?","options":["The cell wall.","The nucleolus.","A lysosome containing digestive enzymes.","A chloroplast containing light-capturing structures."],"answer":2,"explanation":"Lysosomes contain enzymes that digest materials, including worn cell structures. This supports recycling inside the cell. Their role should not be simplified to being the sole cause of apoptosis.","pages":"20–21, 27","sourceStatus":"inherited-unverified","unit":"cells","points":["cells-lysosome"]},{"id":"cells-vacuole","pointKey":"vacuole","stem":"Which role best describes the vacuoles shown in the course's animal-cell model?","options":["Storing water, nutrients, and wastes.","Synthesizing proteins from rRNA.","Organizing spindle microtubules.","Capturing light for photosynthesis."],"answer":0,"explanation":"Vacuoles are membrane-bound storage compartments. The notes show smaller, multiple vacuoles in an animal-cell model, in contrast with the large central vacuole typical of a mature plant cell.","pages":"20–21, 27","sourceStatus":"inherited-unverified","unit":"cells","points":["cells-vacuole"]},{"id":"cells-central-vacuole","pointKey":"central-vacuole","stem":"How does water in the large central vacuole help support a typical mature plant cell?","options":["It replaces the plasma membrane with a rigid shell.","It changes directly into the spindle used in division.","It supplies the ribosomes that make the cell look rough.","It helps maintain turgor pressure as well as providing storage."],"answer":3,"explanation":"The large central vacuole stores materials. Water within it also contributes to turgor pressure, helping support the cell. This is a typical mature plant-cell feature.","pages":"20–21, 27","sourceStatus":"inherited-unverified","unit":"cells","points":["cells-central-vacuole"]},{"id":"cells-centrosome","pointKey":"centrosome","stem":"In a typical animal cell, which structure organizes microtubules for the spindle used to separate chromosomes?","options":["The chloroplast.","The centrosome.","The Golgi apparatus.","The central vacuole."],"answer":1,"explanation":"The centrosome organizes microtubules, including those of the division spindle. A typical animal-cell centrosome contains centrioles made of microtubules; it exists before cell division begins.","pages":"22–23","sourceStatus":"inherited-unverified","unit":"cells","points":["cells-centrosome"]},{"id":"cells-cilia","pointKey":"cilia","stem":"A cell surface has many short projections that move fluid across it. Which structures best fit this description?","options":["Ribosomes.","Nuclear pores.","Cilia.","Central vacuoles."],"answer":2,"explanation":"Cilia are typically short and numerous. They can move fluid across a cell surface or help propel a whole cell. Flagella are usually longer and fewer.","pages":"22–23","sourceStatus":"inherited-unverified","unit":"cells","points":["cells-cilia"]},{"id":"cells-flagella","pointKey":"flagella","stem":"Which structure is usually longer and fewer in number than cilia and can propel a cell?","options":["A flagellum.","A nuclear pore.","A lysosome.","A Golgi sac."],"answer":0,"explanation":"Flagella are usually long movement structures present in relatively small numbers. The notes' '1–3' is a simplified example, not a universal limit. Bacterial and eukaryotic flagella differ in structure.","pages":"22–23","sourceStatus":"inherited-unverified","unit":"cells","points":["cells-flagella"]},{"id":"cells-mitochondria","pointKey":"mitochondria","stem":"Which statement explains why a photosynthetic plant cell also needs mitochondria?","options":["Mitochondria are the structures that capture sunlight.","Mitochondria replace all of the cell's ribosomes.","Mitochondria store water so the cell does not need a vacuole.","Mitochondria convert food-derived energy into ATP through cellular respiration."],"answer":3,"explanation":"Mitochondria are a major site of cellular respiration and ATP production. Photosynthesis does not remove a plant cell's need to use food-derived energy. Mitochondria contain an inner membrane with folds and a matrix.","pages":"24–25","sourceStatus":"inherited-unverified","unit":"cells","points":["cells-mitochondria"]},{"id":"cells-chloroplast","pointKey":"chloroplast","stem":"Which organelle captures light energy to help make sugars and contains grana surrounded by stroma?","options":["The Golgi apparatus.","The chloroplast.","The lysosome.","The centrosome."],"answer":1,"explanation":"Chloroplasts perform photosynthesis. Grana are stacks of membrane sacs, and stroma is the surrounding internal fluid. Not every plant cell contains chloroplasts; algae can have them too.","pages":"24–25","sourceStatus":"inherited-unverified","unit":"cells","points":["cells-chloroplast"]},{"id":"cells-wall","pointKey":"wall","stem":"Which statement correctly describes cell walls?","options":["Animal cells have cellulose walls, while plants lack walls.","Every prokaryotic cell has a cellulose wall.","Plant walls contain cellulose; fungal walls contain chitin; most bacterial walls contain peptidoglycan.","A cell wall is the same structure as the selectively permeable plasma membrane."],"answer":2,"explanation":"Cell walls lie outside the membrane and help protect the cell and maintain its shape. Wall composition differs among groups. Animals lack cell walls, and peptidoglycan is not universal among all prokaryotes.","pages":"8–9, 26, 28–31","sourceStatus":"inherited-unverified","unit":"cells","points":["cells-wall"]},{"id":"cells-comparison","pointKey":"comparison","stem":"Which combination best identifies the photosynthetic plant-cell model rather than the animal-cell model?","options":["A cellulose wall, chloroplasts, and a large central vacuole.","A cell membrane, cytoplasm, and ribosomes.","A nucleus, rough ER, and mitochondria.","DNA, Golgi apparatus, and a cell membrane."],"answer":0,"explanation":"The wall, chloroplasts, and large central vacuole together are characteristic clues in the course's plant-cell diagram. The other sets contain structures shared by typical plant and animal cells. A wall alone is not enough to prove a cell is a plant cell.","pages":"8–9, 26, 28–31","sourceStatus":"inherited-unverified","unit":"cells","points":["cells-comparison"]},{"id":"levels-original-c1","unit":"levels","stem":"Which order runs from simplest to most complex?","options":["Cell → organ → tissue → system → organism","Cell → tissue → organ → system → organism","Tissue → cell → system → organ → organism"],"answer":1,"explanation":"Cells form tissues; different tissues form organs; organs work together in systems. This sequence concerns multicellular organisms with these structures.","pages":"2–6","points":["levels-hierarchy"]},{"id":"levels-original-c2","unit":"levels","stem":"The heart contains muscle, connective, and other tissues. What level is it?","options":["Tissue","Organ system","Organ"],"answer":2,"explanation":"An organ combines different tissues to perform a function. The heart is an organ; the circulatory system is an organ system.","pages":"4","points":["levels-organ"]},{"id":"levels-original-c3","unit":"levels","stem":"Which example belongs to the cell level?","options":["A leaf","An epidermal cell","A root system"],"answer":1,"explanation":"An epidermal cell is one cell. A leaf contains multiple tissues and is an organ. A root system is an organ system.","pages":"2–5","points":["levels-cell"]},{"id":"levels-original-c4","unit":"levels","stem":"The stomach, intestines, and other organs cooperate in digestion. What is their coordinated group?","options":["Organ system","Tissue","Population"],"answer":0,"explanation":"Different organs working together on related functions form an organ system: here, the digestive system.","pages":"5","points":["levels-system"]},{"id":"levels-original-c5","unit":"levels","stem":"One frog, and all the frogs of the same species in a pond, represent which levels?","options":["Organism; community","Organ; organism","Organism; population"],"answer":2,"explanation":"An organism is one individual. A population requires the same area and the same species.","pages":"6–7","points":["levels-organism","levels-population"]},{"id":"levels-original-c6","unit":"levels","stem":"What do all plant, animal, fungal, and microbial populations in a park form?","options":["Community","One population","One organism"],"answer":0,"explanation":"A community includes populations of different species in an area. Multiple species do not form a single population.","pages":"8","points":["levels-community"]},{"id":"levels-original-c7","unit":"levels","stem":"What must be considered in addition to a community to describe an ecosystem?","options":["Only more animals","Nonliving surroundings: water, air, and soil","Only one species"],"answer":1,"explanation":"An ecosystem includes the community and its nonliving environment. Their interactions are also central to understanding an ecosystem.","pages":"9","points":["levels-ecosystem"]},{"id":"levels-original-c8","unit":"levels","stem":"Why is a leaf an organ rather than a tissue?","options":["Because leaves are always larger than every cell","Because every green structure is an organ","Because different tissues work together in a leaf"],"answer":2,"explanation":"Dermal, ground, and vascular tissues cooperate within a leaf. Identify levels by their organization and functions, not just size or color.","pages":"3–4","points":["levels-tissue","levels-organ"]},{"id":"levels-photo-10","unit":"levels","stem":"Which level of organization does the highlighted subject represent? Classify the main subject in the image.","image":"units/levels/images/page-10.jpg","imageAlt":"Classification exercise from source page 10","options":["Cell","Tissue","Organ","Organ system","Organism"],"answer":4,"explanation":"Tree frog: Organism. An organism is an individual living thing made of cells. The notes list energy use, waste removal, growth, response, reproduction, and gas exchange as life processes. ","pages":"10","points":["levels-organism"]},{"id":"levels-photo-11","unit":"levels","stem":"Which level of organization does the highlighted subject represent? Classify the main subject in the image.","image":"units/levels/images/page-11.jpg","imageAlt":"Classification exercise from source page 11","options":["Cell","Tissue","Organ","Organ system","Organism"],"answer":0,"explanation":"Plant cell diagram A: Cell. A cell is the basic unit of structure and function in all living organisms. ","pages":"11","points":["levels-cell"]},{"id":"levels-photo-12","unit":"levels","stem":"Which level of organization does the highlighted subject represent? Classify the main subject in the image.","image":"units/levels/images/page-12.jpg","imageAlt":"Classification exercise from source page 12","options":["Cell","Tissue","Organ","Organ system","Organism"],"answer":3,"explanation":"Human circulation diagram: Organ system. An organ system is a group of different organs working together to perform a particular set of functions. ","pages":"12","points":["levels-system"]},{"id":"levels-photo-13","unit":"levels","stem":"Which level of organization does the highlighted subject represent? Classify the main subject in the image.","image":"units/levels/images/page-13.jpg","imageAlt":"Classification exercise from source page 13","options":["Cell","Tissue","Organ","Organ system","Organism"],"answer":1,"explanation":"White blood cell micrograph: Tissue. A tissue is a group of similar cells working together to perform a specific function. The source classifies this group of blood cells as tissue; it is not an image of one isolated white blood cell.","pages":"13","points":["levels-tissue"]},{"id":"levels-photo-14","unit":"levels","stem":"Which level of organization does the highlighted subject represent? Focus on a bamboo stem.","image":"units/levels/images/page-14.jpg","imageAlt":"Classification exercise from source page 14","options":["Cell","Tissue","Organ","Organ system","Organism"],"answer":2,"explanation":"Bamboo stems: Organ. An organ is made of different tissues working together to perform a specific function. The source targets a bamboo stem as an organ; the photograph shows several stems and a grove without marking one target.","pages":"14","points":["levels-organ"]},{"id":"levels-photo-15","unit":"levels","stem":"Which level of organization does the highlighted subject represent? Classify the main subject in the image.","image":"units/levels/images/page-15.jpg","imageAlt":"Classification exercise from source page 15","options":["Cell","Tissue","Organ","Organ system","Organism"],"answer":4,"explanation":"Snail: Organism. An organism is an individual living thing made of cells. The notes list energy use, waste removal, growth, response, reproduction, and gas exchange as life processes. ","pages":"15","points":["levels-organism"]},{"id":"levels-photo-16","unit":"levels","stem":"Which level of organization does the highlighted subject represent? Classify the main subject in the image.","image":"units/levels/images/page-16.jpg","imageAlt":"Classification exercise from source page 16","options":["Cell","Tissue","Organ","Organ system","Organism"],"answer":0,"explanation":"Animal cell diagram A: Cell. A cell is the basic unit of structure and function in all living organisms. ","pages":"16","points":["levels-cell"]},{"id":"levels-photo-17","unit":"levels","stem":"Which level of organization does the highlighted subject represent? Classify the main subject in the image.","image":"units/levels/images/page-17.jpg","imageAlt":"Classification exercise from source page 17","options":["Cell","Tissue","Organ","Organ system","Organism"],"answer":1,"explanation":"Red blood cells: Tissue. A tissue is a group of similar cells working together to perform a specific function. The source uses the group of red blood cells as a blood-tissue example; many individual cells are visible.","pages":"17","points":["levels-tissue"]},{"id":"levels-photo-18","unit":"levels","stem":"Which level of organization does the highlighted subject represent? Classify the main subject in the image.","image":"units/levels/images/page-18.jpg","imageAlt":"Classification exercise from source page 18","options":["Cell","Tissue","Organ","Organ system","Organism"],"answer":4,"explanation":"Stick insect: Organism. An organism is an individual living thing made of cells. The notes list energy use, waste removal, growth, response, reproduction, and gas exchange as life processes. ","pages":"18","points":["levels-organism"]},{"id":"levels-photo-19","unit":"levels","stem":"Which level of organization does the highlighted subject represent? Classify the main subject in the image.","image":"units/levels/images/page-19.jpg","imageAlt":"Classification exercise from source page 19","options":["Cell","Tissue","Organ","Organ system","Organism"],"answer":1,"explanation":"Green cell micrograph: Tissue. A tissue is a group of similar cells working together to perform a specific function. The source classifies the group of plant cells as tissue; individual cells are also visible.","pages":"19","points":["levels-tissue"]},{"id":"levels-photo-20","unit":"levels","stem":"Which level of organization does the highlighted subject represent? Classify the main subject in the image.","image":"units/levels/images/page-20.jpg","imageAlt":"Classification exercise from source page 20","options":["Cell","Tissue","Organ","Organ system","Organism"],"answer":3,"explanation":"Swordfish skeleton: Organ system. An organ system is a group of different organs working together to perform a particular set of functions. ","pages":"20","points":["levels-system"]},{"id":"levels-photo-21","unit":"levels","stem":"Which level of organization does the highlighted subject represent? Classify the main subject in the image.","image":"units/levels/images/page-21.jpg","imageAlt":"Classification exercise from source page 21","options":["Cell","Tissue","Organ","Organ system","Organism"],"answer":4,"explanation":"Whole tree: Organism. An organism is an individual living thing made of cells. The notes list energy use, waste removal, growth, response, reproduction, and gas exchange as life processes. ","pages":"21","points":["levels-organism"]},{"id":"levels-photo-22","unit":"levels","stem":"Which level of organization does the highlighted subject represent? Classify the main subject in the image.","image":"units/levels/images/page-22.jpg","imageAlt":"Classification exercise from source page 22","options":["Cell","Tissue","Organ","Organ system","Organism"],"answer":2,"explanation":"Autumn leaf: Organ. An organ is made of different tissues working together to perform a specific function. ","pages":"22","points":["levels-organ"]},{"id":"levels-photo-23","unit":"levels","stem":"Which level of organization does the highlighted subject represent? Classify the main subject in the image.","image":"units/levels/images/page-23.jpg","imageAlt":"Classification exercise from source page 23","options":["Cell","Tissue","Organ","Organ system","Organism"],"answer":0,"explanation":"Plant cell diagram B: Cell. A cell is the basic unit of structure and function in all living organisms. ","pages":"23","points":["levels-cell"]},{"id":"levels-photo-24","unit":"levels","stem":"Which level of organization does the highlighted subject represent? Classify the main subject in the image.","image":"units/levels/images/page-24.jpg","imageAlt":"Classification exercise from source page 24","options":["Cell","Tissue","Organ","Organ system","Organism"],"answer":2,"explanation":"Heart: Organ. An organ is made of different tissues working together to perform a specific function. ","pages":"24","points":["levels-organ"]},{"id":"levels-photo-25","unit":"levels","stem":"Which level of organization does the highlighted subject represent? Classify the main subject in the image.","image":"units/levels/images/page-25.jpg","imageAlt":"Classification exercise from source page 25","options":["Cell","Tissue","Organ","Organ system","Organism"],"answer":2,"explanation":"Apple: Organ. An organ is made of different tissues working together to perform a specific function. ","pages":"25","points":["levels-organ"]},{"id":"levels-photo-26","unit":"levels","stem":"Which level of organization does the highlighted subject represent? Classify the main subject in the image.","image":"units/levels/images/page-26.jpg","imageAlt":"Classification exercise from source page 26","options":["Cell","Tissue","Organ","Organ system","Organism"],"answer":4,"explanation":"Grass with roots exposed: Organism. An organism is an individual living thing made of cells. The notes list energy use, waste removal, growth, response, reproduction, and gas exchange as life processes. Shoots and roots are both visible, and the source classifies the plant as an organism; the prominent roots alone should not change the source answer to a root system.","pages":"26","points":["levels-organism"]},{"id":"levels-photo-27","unit":"levels","stem":"Which level of organization does the highlighted subject represent? Focus on the lungs.","image":"units/levels/images/page-27.jpg","imageAlt":"Classification exercise from source page 27","options":["Cell","Tissue","Organ","Organ system","Organism"],"answer":2,"explanation":"Lungs: Organ. An organ is made of different tissues working together to perform a specific function. The main subject is a pair of lungs with the trachea and some bronchi; the source answer is organ.","pages":"27","points":["levels-organ"]},{"id":"levels-photo-28","unit":"levels","stem":"Which level of organization does the highlighted subject represent? Classify the main subject in the image.","image":"units/levels/images/page-28.jpg","imageAlt":"Classification exercise from source page 28","options":["Cell","Tissue","Organ","Organ system","Organism"],"answer":3,"explanation":"Tree roots: Organ system. An organ system is a group of different organs working together to perform a particular set of functions. ","pages":"28","points":["levels-system"]},{"id":"levels-photo-29","unit":"levels","stem":"Which level of organization does the highlighted subject represent? Classify the main subject in the image.","image":"units/levels/images/page-29.jpg","imageAlt":"Classification exercise from source page 29","options":["Cell","Tissue","Organ","Organ system","Organism"],"answer":4,"explanation":"Sloth: Organism. An organism is an individual living thing made of cells. The notes list energy use, waste removal, growth, response, reproduction, and gas exchange as life processes. ","pages":"29","points":["levels-organism"]},{"id":"levels-photo-30","unit":"levels","stem":"Which level of organization does the highlighted subject represent? Classify the main subject in the image.","image":"units/levels/images/page-30.jpg","imageAlt":"Classification exercise from source page 30","options":["Cell","Tissue","Organ","Organ system","Organism"],"answer":1,"explanation":"Rows of plant cells: Tissue. A tissue is a group of similar cells working together to perform a specific function. The source classifies this multicellular plant section as tissue; no specific tissue is named.","pages":"30","points":["levels-tissue"]},{"id":"levels-photo-31","unit":"levels","stem":"Which level of organization does the highlighted subject represent? Classify the main subject in the image.","image":"units/levels/images/page-31.jpg","imageAlt":"Classification exercise from source page 31","options":["Cell","Tissue","Organ","Organ system","Organism"],"answer":3,"explanation":"Bird breathing diagram: Organ system. An organ system is a group of different organs working together to perform a particular set of functions. ","pages":"31","points":["levels-system"]},{"id":"levels-photo-32","unit":"levels","stem":"Which level of organization does the highlighted subject represent? Classify the main subject in the image.","image":"units/levels/images/page-32.jpg","imageAlt":"Classification exercise from source page 32","options":["Cell","Tissue","Organ","Organ system","Organism"],"answer":2,"explanation":"Stomach: Organ. An organ is made of different tissues working together to perform a specific function. ","pages":"32","points":["levels-organ"]},{"id":"levels-photo-33","unit":"levels","stem":"Which level of organization does the highlighted subject represent? Classify the main subject in the image.","image":"units/levels/images/page-33.jpg","imageAlt":"Classification exercise from source page 33","options":["Cell","Tissue","Organ","Organ system","Organism"],"answer":2,"explanation":"Purple aquatic flower: Organ. An organ is made of different tissues working together to perform a specific function. ","pages":"33","points":["levels-organ"]},{"id":"levels-photo-34","unit":"levels","stem":"Which level of organization does the highlighted subject represent? Focus on the liver.","image":"units/levels/images/page-34.jpg","imageAlt":"Classification exercise from source page 34","options":["Cell","Tissue","Organ","Organ system","Organism"],"answer":2,"explanation":"Liver: Organ. An organ is made of different tissues working together to perform a specific function. The main subject is the liver, with a gallbladder and ducts also drawn; the source answer is organ.","pages":"34","points":["levels-organ"]},{"id":"levels-photo-35","unit":"levels","stem":"Which level of organization does the highlighted subject represent? Focus on the prominent main root.","image":"units/levels/images/page-35.jpg","imageAlt":"Classification exercise from source page 35","options":["Cell","Tissue","Organ","Organ system","Organism"],"answer":2,"explanation":"Taproot in soil: Organ. An organ is made of different tissues working together to perform a specific function. The photograph emphasizes a taproot and lateral roots, with a small part of the shoot at the top; the source targets the root as an organ.","pages":"35","points":["levels-organ"]},{"id":"levels-photo-36","unit":"levels","stem":"Which level of organization does the highlighted subject represent? Classify the main subject in the image.","image":"units/levels/images/page-36.jpg","imageAlt":"Classification exercise from source page 36","options":["Cell","Tissue","Organ","Organ system","Organism"],"answer":0,"explanation":"Animal cell diagram B: Cell. A cell is the basic unit of structure and function in all living organisms. ","pages":"36","points":["levels-cell"]},{"id":"levels-photo-37","unit":"levels","stem":"Which level of organization does the highlighted subject represent? Classify the main subject in the image.","image":"units/levels/images/page-37.jpg","imageAlt":"Classification exercise from source page 37","options":["Cell","Tissue","Organ","Organ system","Organism"],"answer":3,"explanation":"Spinach shoot: Organ system. An organ system is a group of different organs working together to perform a particular set of functions. The image shows connected stems and leaves without complete roots; the source classifies the shoot as a system.","pages":"37","points":["levels-system"]},{"id":"levels-photo-39","unit":"levels","stem":"Which level of organization does the highlighted subject represent? Classify the small and large intestines as individual structures.","image":"units/levels/images/page-39.jpg","imageAlt":"Classification exercise from source page 39","options":["Cell","Tissue","Organ","Organ system","Organism"],"answer":2,"explanation":"Small and large intestines: Organ. An organ is made of different tissues working together to perform a specific function. The small and large intestines are individual organs. The source uses the plural organs; showing several organs in one picture does not make each one an entire organ system.","pages":"39","points":["levels-organ"]},{"id":"levels-photo-40","unit":"levels","stem":"Which level of organization does the highlighted subject represent? Classify the main subject in the image.","image":"units/levels/images/page-40.jpg","imageAlt":"Classification exercise from source page 40","options":["Cell","Tissue","Organ","Organ system","Organism"],"answer":0,"explanation":"Plant cell diagram C: Cell. A cell is the basic unit of structure and function in all living organisms. ","pages":"40","points":["levels-cell"]},{"id":"levels-photo-41","unit":"levels","stem":"Which level of organization does the highlighted subject represent? Classify the main subject in the image.","image":"units/levels/images/page-41.jpg","imageAlt":"Classification exercise from source page 41","options":["Cell","Tissue","Organ","Organ system","Organism"],"answer":3,"explanation":"Hanging plant roots: Organ system. An organ system is a group of different organs working together to perform a particular set of functions. The image emphasizes multiple roots; part of the stem base is also visible. The source classifies the root system.","pages":"41","points":["levels-system"]},{"id":"levels-photo-42","unit":"levels","stem":"Which level of organization does the highlighted subject represent? Classify each plant with its root and leafy shoot.","image":"units/levels/images/page-42.jpg","imageAlt":"Classification exercise from source page 42","options":["Cell","Tissue","Organ","Organ system","Organism"],"answer":4,"explanation":"Carrots with leafy tops: Organism. An organism is an individual living thing made of cells. The notes list energy use, waste removal, growth, response, reproduction, and gas exchange as life processes. The source treats the carrots with roots and leafy shoots as whole plants. Several are pictured together, rather than detached roots alone.","pages":"42","points":["levels-organism"]},{"id":"levels-photo-43","unit":"levels","stem":"Which level of organization does the highlighted subject represent? Classify the main subject in the image.","image":"units/levels/images/page-43.jpg","imageAlt":"Classification exercise from source page 43","options":["Cell","Tissue","Organ","Organ system","Organism"],"answer":1,"explanation":"Muscle micrograph: Tissue. A tissue is a group of similar cells working together to perform a specific function. The image shows a muscle section; the source does not specify the muscle tissue type.","pages":"43","points":["levels-tissue"]},{"id":"levels-photo-44","unit":"levels","stem":"Which level of organization does the highlighted subject represent? Classify the main subject in the image.","image":"units/levels/images/page-44.jpg","imageAlt":"Classification exercise from source page 44","options":["Cell","Tissue","Organ","Organ system","Organism"],"answer":4,"explanation":"Seedling with exposed roots: Organism. An organism is an individual living thing made of cells. The notes list energy use, waste removal, growth, response, reproduction, and gas exchange as life processes. Both the shoot and roots are visible; the source provides no image credit URL.","pages":"44","points":["levels-organism"]},{"id":"levels-photo-45","unit":"levels","stem":"Which level of organization does the highlighted subject represent? Classify the main subject in the image.","image":"units/levels/images/page-45.jpg","imageAlt":"Classification exercise from source page 45","options":["Cell","Tissue","Organ","Organ system","Organism"],"answer":3,"explanation":"Digestive anatomy diagram: Organ system. An organ system is a group of different organs working together to perform a particular set of functions. ","pages":"45","points":["levels-system"]},{"id":"levels-photo-46","unit":"levels","stem":"Which level of organization does the highlighted subject represent? Focus on a bud on the twig.","image":"units/levels/images/page-46.jpg","imageAlt":"Classification exercise from source page 46","options":["Cell","Tissue","Organ","Organ system","Organism"],"answer":2,"explanation":"Buds on a twig: Organ. An organ is made of different tissues working together to perform a specific function. The source targets the bud as an organ; a twig and several buds are visible.","pages":"46","points":["levels-organ"]},{"id":"levels-photo-47","unit":"levels","stem":"Which level of organization does the highlighted subject represent? Classify the main subject in the image.","image":"units/levels/images/page-47.jpg","imageAlt":"Classification exercise from source page 47","options":["Cell","Tissue","Organ","Organ system","Organism"],"answer":0,"explanation":"Animal cell diagram C: Cell. A cell is the basic unit of structure and function in all living organisms. ","pages":"47","points":["levels-cell"]},{"id":"levels-photo-48","unit":"levels","stem":"Which level of organization does the highlighted subject represent? Classify the main subject in the image.","image":"units/levels/images/page-48.jpg","imageAlt":"Classification exercise from source page 48","options":["Cell","Tissue","Organ","Organ system","Organism"],"answer":3,"explanation":"Human nerve diagram: Organ system. An organ system is a group of different organs working together to perform a particular set of functions. ","pages":"48","points":["levels-system"]},{"id":"levels-photo-49","unit":"levels","stem":"Which level of organization does the highlighted subject represent? Classify the main subject in the image.","image":"units/levels/images/page-49.jpg","imageAlt":"Classification exercise from source page 49","options":["Cell","Tissue","Organ","Organ system","Organism"],"answer":2,"explanation":"Brain: Organ. An organ is made of different tissues working together to perform a specific function. ","pages":"49","points":["levels-organ"]},{"id":"levels-photo-51","unit":"levels","stem":"Which level of organization does the highlighted subject represent? Classify the main subject in the image.","image":"units/levels/images/page-51.jpg","imageAlt":"Classification exercise from source page 51","options":["Cell","Tissue","Organ","Organ system","Organism"],"answer":3,"explanation":"Deer muscle diagram: Organ system. An organ system is a group of different organs working together to perform a particular set of functions. The diagram shows the distribution of many muscles; the source classifies the group as a muscular system.","pages":"51","points":["levels-system"]},{"id":"levels-photo-52","unit":"levels","stem":"Which level of organization does the highlighted subject represent? Classify the main subject in the image.","image":"units/levels/images/page-52.jpg","imageAlt":"Classification exercise from source page 52","options":["Cell","Tissue","Organ","Organ system","Organism"],"answer":4,"explanation":"Sea turtle: Organism. An organism is an individual living thing made of cells. The notes list energy use, waste removal, growth, response, reproduction, and gas exchange as life processes. ","pages":"52","points":["levels-organism"]},{"id":"cells-original-1","unit":"cells","stem":"Which statement agrees with cell theory?","options":["Every living organism contains many cells.","New cells form without pre-existing cells.","Cells are life's basic units and arise from existing cells.","Organs are the smallest living units."],"answer":2,"explanation":"Living things consist of cells. Unicellular organisms have one cell; multicellular organisms have many, which may form tissues, organs, and organ systems.","pages":"2–3","points":["cells-theory"]},{"id":"cells-original-2","unit":"cells","stem":"Which comparison correctly describes typical prokaryotic and eukaryotic cells?","options":["Prokaryotes lack a membrane-bound nucleus; eukaryotes have one.","Only eukaryotes have ribosomes.","Only prokaryotes have a cell membrane.","All eukaryotic organisms are multicellular."],"answer":0,"explanation":"Both share a membrane, cytoplasm, ribosomes, and DNA. Eukaryotes have membrane-bound organelles and may be unicellular or multicellular.","pages":"4–7","points":["cells-prokaryote","cells-eukaryote"]},{"id":"cells-original-3","unit":"cells","stem":"Which set correctly matches the membrane, cytoplasm, and cytoskeleton?","options":["Membrane: stores DNA; cytoplasm: rigid shell; cytoskeleton: makes sugars","Membrane: regulates exchange; cytoplasm: watery interior; cytoskeleton: supporting protein fibers","Membrane: makes ATP; cytoplasm: cell wall; cytoskeleton: digestive sac","Membrane: completely impermeable; cytoplasm: pure DNA; cytoskeleton: pure lipid"],"answer":1,"explanation":"The membrane is a phospholipid bilayer with proteins. Cytoplasm provides an internal medium; the cytoskeleton maintains shape and helps move organelles.","pages":"10–13","points":["cells-membrane","cells-cytoplasm","cells-cytoskeleton"]},{"id":"cells-original-4","unit":"cells","stem":"What are the main roles of the nucleus and nucleolus?","options":["The nucleus makes lipids; the nucleolus digests food.","The nucleus performs photosynthesis; the nucleolus stores water.","The nucleus packages proteins; the nucleolus propels the cell.","The nucleus protects DNA; the nucleolus makes rRNA and helps assemble ribosomal subunits."],"answer":3,"explanation":"Nuclear DNA provides genetic information, and nuclear pores regulate exchange. The nucleolus lies inside the nucleus and helps form ribosomes.","pages":"14–15","points":["cells-nucleus","cells-nucleolus"]},{"id":"cells-original-5","unit":"cells","stem":"Why does rough ER look rough, and what do its attached structures do?","options":["Ribosomes are attached to its surface; they synthesize proteins.","Chloroplasts are attached; they capture light.","Vacuoles are attached; they store water.","Cilia are attached; they move fluid."],"answer":0,"explanation":"Ribosomes contain rRNA and proteins and may be free in the cytoplasm or attached to rough ER. Rough ER helps process and transport proteins.","pages":"16–17","points":["cells-ribosome","cells-rough-er"]},{"id":"cells-original-6","unit":"cells","stem":"Which set correctly describes smooth ER, the Golgi apparatus, and vesicles?","options":["Smooth ER stores DNA; Golgi makes rRNA; vesicles perform photosynthesis.","Smooth ER makes lipids; Golgi processes and sorts; vesicles transport materials.","Smooth ER is covered in ribosomes; Golgi only stores water; vesicles separate chromosomes.","All three only make ATP."],"answer":1,"explanation":"Smooth ER lacks attached ribosomes and synthesizes lipids. The Golgi receives ER vesicles, then processes, sorts, and ships their contents, including proteins.","pages":"18–19","points":["cells-smooth-er","cells-golgi","cells-vesicle"]},{"id":"cells-original-7","unit":"cells","stem":"Which pair correctly compares lysosomes and vacuoles?","options":["Lysosomes perform photosynthesis; vacuoles synthesize proteins.","Lysosomes store chromosomes; vacuoles move cells.","Lysosomes digest materials using enzymes; vacuoles store water, nutrients, and wastes.","Lysosomes synthesize lipids; vacuoles make rRNA."],"answer":2,"explanation":"Lysosomes digest and recycle worn cell components. The large central vacuole of a typical mature plant cell stores materials and helps maintain turgor.","pages":"20–21, 27","points":["cells-lysosome","cells-vacuole"]},{"id":"cells-original-8","unit":"cells","stem":"Which set gives the usual roles of centrosomes, cilia, and flagella?","options":["Centrosome: photosynthesis; cilia: storage; flagellum: digestion","Centrosome: DNA synthesis; cilia: lipids; flagellum: proteins","Centrosome: storage; cilia: protein packaging; flagellum: ATP synthesis","Centrosome: organizes division microtubules; cilia: move surface fluid; flagellum: propels a cell"],"answer":3,"explanation":"Centrioles in the centrosome are made of microtubules. Centrosomes organize division microtubules; cilia are usually short and numerous, while flagella are longer and fewer.","pages":"22–23","points":["cells-centrosome","cells-cilia","cells-flagella"]},{"id":"cells-original-9","unit":"cells","stem":"Which pairing correctly compares mitochondria and chloroplasts?","options":["Mitochondria: respiration and ATP; chloroplasts: photosynthesis and sugars","Mitochondria: photosynthesis; chloroplasts: digestion","Mitochondria: protein shipping; chloroplasts: chromosome movement","Both only store water and wastes."],"answer":0,"explanation":"Mitochondria convert food-derived energy into ATP and contain a matrix. Chloroplasts capture light to help make sugars and contain grana and stroma. Plant cells also have mitochondria.","pages":"24–25","points":["cells-mitochondria","cells-chloroplast"]},{"id":"cells-original-10","unit":"cells","stem":"A diagram shows a cellulose wall, chloroplasts, and a large central vacuole. Which cell best fits?","options":["A typical animal cell","A bacterial cell","A photosynthetic plant cell","A typical fungal cell"],"answer":2,"explanation":"This combination matches the plant-cell model. Animals lack cell walls; fungal walls mainly contain chitin; bacteria lack chloroplasts. Cell walls help protect cells and maintain shape.","pages":"8–9, 26, 28–31","points":["cells-comparison"]}],"discussions":[{"id":"levels-photo-38","unit":"levels","stem":"Which level of organization does the highlighted subject represent? Classify the main subject in the image.","image":"units/levels/images/page-38.jpg","imageAlt":"Classification exercise from source page 38","options":["Cell","Tissue","Organ","Organ system","Organism"],"answer":3,"explanation":"Seedling above soil: Organ system. An organ system is a group of different organs working together to perform a particular set of functions. Ambiguous: the source answer is plant system, apparently targeting the shoot. Roots are hidden in soil, so the picture can also be read as a whole seedling.","pages":"38","points":["levels-system"]},{"id":"levels-photo-50","unit":"levels","stem":"Which level of organization does the highlighted subject represent? Classify the main subject in the image.","image":"units/levels/images/page-50.jpg","imageAlt":"Classification exercise from source page 50","options":["Cell","Tissue","Organ","Organ system","Organism"],"answer":1,"explanation":"Leaf and vein close-up: Tissue. A tissue is a group of similar cells working together to perform a specific function. Ambiguous: the source answer is plant tissue. The photograph is a leaf-and-vein close-up with no specific tissue marked, so the image can also be read as part of a leaf organ.","pages":"50","points":["levels-tissue"]}],"uniquePointCount":37,"countingRule":"One named learning objective per concept or fact card, with definitions, functions and examples grouped. The Levels unit has eight named levels plus hierarchy and life processes. The Cells unit has 27 fact cards in 10 groups. Related content across the units is cross-referenced; no complete objectives are equivalent, so all 37 remain after deduplication."};
